#!/usr/bin/env node
/**
 * generate-unwired-engine-wiki.mjs
 *
 * Closes the `ghost.unwired-engine` wiki gap (L13, 636 nodes in WIKI-COVERAGE-AUDIT
 * 2026-05-23). The companion `generate-engine-wiki.mjs` covers L5 `atomic_engine`
 * nodes (wired engines), but unwired engines on disk get no wiki coverage and
 * therefore can't be discovered by tribal-by-domain-inject / master-index /
 * Claude's PSN recall.
 *
 * Reads `state/shared/UNWIRED-ENGINE-AUDIT-2026-05-07.json` (the canonical
 * 611-engine list, regenerated by scripts/audit-unwired-engines.mjs) and emits
 * one Obsidian wiki stub per entry at
 *   `knowledge/wiki/architecture/engines-unwired/<EngineName>.md`
 *
 * Each stub surfaces engine name, source path, mtime, suggested dispatcher,
 * and a "needs wiring" callout that makes the engine discoverable + actionable
 * by AI systems and operators. Idempotent — AUTO-START/END markers preserve
 * human content. Updates `knowledge/wiki/index.md` with an engines-unwired
 * count summary.
 *
 * Flags:
 *   --dry-run        skip writes, report count only
 *   --limit=N        process only first N entries (useful for testing)
 *   --audit=<path>   override unwired-audit JSON path
 *
 * Exit codes: 0 = success, 2 = missing audit input.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { resolve, dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const PRISM_ROOT = resolve(__dirname, "..");
const DEFAULT_AUDIT = resolve(PRISM_ROOT, "state/shared/UNWIRED-ENGINE-AUDIT-2026-05-07.json");
const WIKI_ARCH_DIR = resolve(PRISM_ROOT, "knowledge/wiki/architecture");
const WIKI_OUT_DIR = join(WIKI_ARCH_DIR, "engines-unwired");
const WIKI_INDEX = resolve(PRISM_ROOT, "knowledge/wiki/index.md");
const ENGINES_SRC_REL = "mcp-server/src/engines";

const args = process.argv.slice(2);
const FLAGS = {
  dryRun: args.includes("--dry-run"),
  limit: Number((args.find((a) => a.startsWith("--limit=")) || "").split("=")[1]) || 0,
  auditPath: (args.find((a) => a.startsWith("--audit=")) || "").split("=")[1] || DEFAULT_AUDIT,
};

const AUTO_START = "<!-- AUTO-START — regenerated by generate-unwired-engine-wiki.mjs -->";
const AUTO_END = "<!-- AUTO-END -->";

function slug(s) {
  return String(s || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function ensureDir(d) {
  if (!existsSync(d)) mkdirSync(d, { recursive: true });
}

function guessSourcePath(engineName) {
  const candidate = join(PRISM_ROOT, ENGINES_SRC_REL, `${engineName}.ts`);
  if (existsSync(candidate)) return `${ENGINES_SRC_REL}/${engineName}.ts`;
  return null;
}

/**
 * Render the markdown body for a single unwired-engine wiki stub.
 * Pure — exported for test fixtures.
 */
export function renderUnwiredEngine(entry, generatedAt) {
  const name = String(entry.engine || "").trim();
  const mtime = String(entry.mtime || "unknown").slice(0, 10);
  const sizeKb = Number(entry.size_kb || 0);
  const suggestion = String(entry.suggestedDispatcher || "UNKNOWN — review manually");
  const sourcePath = guessSourcePath(name);
  const sourceLine = sourcePath
    ? `\`${sourcePath}\``
    : `_(source not at expected path — check subdirs of \`${ENGINES_SRC_REL}/\`)_`;
  const dispatcherLine = suggestion === "UNKNOWN — review manually"
    ? "_(needs manual review — no dispatcher suggested)_"
    : `\`${suggestion}\` (suggested — verify before wiring)`;
  return `---
title: ${name}
type: engine
engine_name: ${name}
status: unwired
parent_layer: L13
ghost_node_kind: ghost.unwired-engine
last_modified_source: ${mtime}
size_kb: ${sizeKb}
suggested_dispatcher: ${JSON.stringify(suggestion)}
generated_by: scripts/generate-unwired-engine-wiki.mjs
last_verified: ${generatedAt}
tags: [engine, unwired, ghost, needs-wiring, atomic]
related:
  - state/shared/UNWIRED-ENGINE-AUDIT-2026-05-07.json
  - state/shared/BUILD_STATE.md
  - knowledge/wiki/architecture/engine-wiring.md
---

# ${name} — UNWIRED

> Engine exists on disk but has **no dispatcher reference**. Not invocable until wired.

${AUTO_START}

## Status

| Field | Value |
|-------|-------|
| Engine name | \`${name}\` |
| Status | **unwired** |
| Layer (graph) | L13 (ghost.unwired-engine) |
| Source mtime | ${mtime} |
| Size | ${sizeKb} KB |

## Source

${sourceLine}

## Suggested dispatcher

${dispatcherLine}

## Wiring next steps

1. Read the engine source to identify its primary domain (force/CAM/CAD/safety/etc.).
2. Pick the natural primary dispatcher (\`prism_calc\`, \`prism_cam\`, \`prism_safety\`, …).
3. Add a lazy import in the dispatcher, register an action in its \`z.enum\`, wire a schema, and write a round-trip test.
4. Per CLAUDE.md §ENGINE WIRING — WIRE TO ALL SOURCES, also wire to every dispatcher that would naturally consume it.
5. After wiring, this entry auto-graduates to a wired-engine entry on the next \`generate-engine-wiki.mjs\` run.

## Why this stub exists

Unwired engines previously had NO wiki coverage → invisible to \`tribal-by-domain-inject\`, \`master-index\`, and PSN recall. This stub makes them **discoverable** so AI systems and operators can find + wire them. Stubs are minimal by design; once wired, the canonical \`generate-engine-wiki.mjs\` produces the full entry under \`knowledge/wiki/architecture/engines/<domain>/\`.

${AUTO_END}

## See also

- Canonical unwired-engine inventory: \`state/shared/UNWIRED-ENGINE-AUDIT-2026-05-07.json\`
- Live BUILD_STATE snapshot: \`state/shared/BUILD_STATE.md\`
- WIRE-TO-ALL-SOURCES doctrine: \`H:/prism/CLAUDE.md\` §ENGINE WIRING
`;
}

function preserveHuman(existing, full) {
  if (!existing) return full;
  const sStart = existing.indexOf(AUTO_START);
  const sEnd = existing.indexOf(AUTO_END);
  const nStart = full.indexOf(AUTO_START);
  const nEnd = full.indexOf(AUTO_END);
  if (sStart === -1 || sEnd === -1) return full;
  const before = existing.slice(0, sStart);
  const after = existing.slice(sEnd + AUTO_END.length);
  const newAuto = full.slice(nStart, nEnd + AUTO_END.length);
  return before + newAuto + after;
}

function updateIndex(count) {
  if (!existsSync(WIKI_INDEX)) return null;
  const text = readFileSync(WIKI_INDEX, "utf8");
  const block = [
    "<!-- ARCH-ENGINES-UNWIRED-START -->",
    `- unwired engines: ${count} stubs — see \`knowledge/wiki/architecture/engines-unwired/\``,
    "<!-- ARCH-ENGINES-UNWIRED-END -->",
  ].join("\n");
  if (text.includes("<!-- ARCH-ENGINES-UNWIRED-START -->")) {
    return text.replace(/<!-- ARCH-ENGINES-UNWIRED-START -->[\s\S]*?<!-- ARCH-ENGINES-UNWIRED-END -->/m, block);
  }
  if (text.includes("<!-- ARCH-ENGINES-END -->")) {
    return text.replace(
      /<!-- ARCH-ENGINES-END -->/,
      "<!-- ARCH-ENGINES-END -->\n\n### Engines (unwired stubs — discoverability layer)\n\n" + block
    );
  }
  return text.trimEnd() + "\n\n### Engines (unwired stubs)\n\n" + block + "\n";
}

function main() {
  if (!existsSync(FLAGS.auditPath)) {
    console.error(`unwired-engine audit missing at ${FLAGS.auditPath}`);
    process.exit(2);
  }
  const audit = JSON.parse(readFileSync(FLAGS.auditPath, "utf8"));
  const entries = Array.isArray(audit.unwiredEngines) ? audit.unwiredEngines : [];
  const slice = FLAGS.limit > 0 ? entries.slice(0, FLAGS.limit) : entries;

  ensureDir(WIKI_OUT_DIR);
  const generatedAt = new Date().toISOString().split("T")[0];

  let written = 0;
  let skipped = 0;
  const t0 = Date.now();

  for (const entry of slice) {
    const name = String(entry.engine || "").trim();
    if (!name) {
      skipped++;
      continue;
    }
    const fileName = `${slug(name)}.md`;
    const outPath = join(WIKI_OUT_DIR, fileName);
    const existing = existsSync(outPath) ? readFileSync(outPath, "utf8") : null;
    const full = renderUnwiredEngine(entry, generatedAt);
    const finalContent = preserveHuman(existing, full);
    if (!FLAGS.dryRun) writeFileSync(outPath, finalContent, "utf8");
    written++;
  }

  const indexUpdated = !FLAGS.dryRun ? updateIndex(written) : null;
  if (indexUpdated && !FLAGS.dryRun) writeFileSync(WIKI_INDEX, indexUpdated, "utf8");

  console.log(
    `generated ${written} unwired-engine wiki entries in ${Date.now() - t0}ms (skipped ${skipped}, dry-run: ${FLAGS.dryRun})`
  );
}

// Direct CLI invocation only — module imports get renderUnwiredEngine without
// triggering the writer. pathToFileURL handles Windows triple-slash and
// drive-letter encoding correctly (the manual ${"file://"} concat does not).
const isDirectInvoke = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isDirectInvoke) main();
